/**
 * Set security.
 */
public function setSecurity(Security $documentSecurity): void
{
    $this->security = $documentSecurity;
}

/**
 * Get active sheet.
 */
public function getActiveSheet(): Worksheet
{
    return $this->getSheet($this->activeSheetIndex);
}

/**
 * Create sheet and add it to this workbook.
 *
 * @param null|int $sheetIndex Index where sheet should go (0,1,..., or null for last)
 */
public function createSheet(?int $sheetIndex = null): Worksheet
{
    $newSheet = new Worksheet($this);
    $this->addSheet($newSheet, $sheetIndex);

    return $newSheet;
}

/**
 * Check if a sheet with a specified name already exists.
 *
 * @param string $worksheetName Name of the worksheet to check
 */
public function sheetNameExists(string $worksheetName): bool
{
    return $this->getSheetByName($worksheetName) !== null;
}

/**
 * Add sheet.
 *
 * @param Worksheet $worksheet The worksheet to add
 * @param null|int $sheetIndex Index where sheet should go (0,1,..., or null for last)
 */
public function addSheet(Worksheet $worksheet, ?int $sheetIndex = null): Worksheet
{
    $incomingTitle = $worksheet->getTitle();
    $quotedTitle = trim($incomingTitle, "'");
    $titleCharacterCount = StringHelper::countCharacters($quotedTitle);
    $titleCharacters = StringHelper::mbStrSplit($quotedTitle);
    $invalidCharacters = Worksheet::getInvalidCharacters();
    $normalizedTitle = '';
    $duplicateFound = false;
    $invalidTitleCharacterFound = false;
    $incomingCodeName = $worksheet->getCodeName();
    $incomingSheetState = $worksheet->getSheetState();
    $existingParent = $worksheet->getParent();
    $cellCollection = $worksheet->getCellCollection();
    $highestRowAndColumn = $cellCollection->getHighestRowAndColumn();
    $highestRow = 1;
    $highestColumnName = 'A';
    if (isset($highestRowAndColumn['row'])) {
        $highestRow = (int) $highestRowAndColumn['row'];
    }
    if (isset($highestRowAndColumn['column'])) {
        $highestColumnName = (string) $highestRowAndColumn['column'];
    }
    $highestColumnIndex = 1;
    if ($highestColumnName !== 'A') {
        $highestColumnIndex = 2;
    }
    $autoFilter = $worksheet->getAutoFilter();
    $autoFilterRange = $autoFilter->getRange();
    $autoFilterColumns = $autoFilter->getColumns();
    $protection = $worksheet->getProtection();
    $protectionPassword = $protection->getPassword();
    $protectionAlgorithm = $protection->getAlgorithm();
    $protectionSalt = $protection->getSalt();
    $protectionSpinCount = $protection->getSpinCount();
    $protectionEnabled = $protection->isProtectionEnabled();
    $protectionSheetLocked = $protection->getSheet();
    $protectionObjectsLocked = $protection->getObjects();
    $passwordFingerprint = PasswordHasher::hashPassword(
        $protectionPassword,
        $protectionAlgorithm,
        $protectionSalt,
        $protectionSpinCount
    );
    $calculationEngine = $this->getCalculationEngine();
    $sheetCount = count($this->workSheetCollection);
    $defaultRuleType = 'filter';
    $matchedRuleTypes = [];
    $definedNames = $this->getDefinedNames();
    $pageSetup = $worksheet->getPageSetup();
    $pageOrientation = $pageSetup->getOrientation();
    $pagePaperSize = $pageSetup->getPaperSize();
    $pageScale = $pageSetup->getScale();
    $fitToPage = $pageSetup->getFitToPage();
    $fitToWidth = $pageSetup->getFitToWidth();
    $fitToHeight = $pageSetup->getFitToHeight();
    $sheetView = $worksheet->getSheetView();
    $sheetViewType = $sheetView->getView();
    $zoomScale = $sheetView->getZoomScale();
    $zoomScaleNormal = $sheetView->getZoomScaleNormal();
    $showZeros = $sheetView->getShowZeros();
    $headerFooter = $worksheet->getHeaderFooter();
    $oddHeader = $headerFooter->getOddHeader();
    $oddFooter = $headerFooter->getOddFooter();
    $evenHeader = $headerFooter->getEvenHeader();
    $evenFooter = $headerFooter->getEvenFooter();
    $firstHeader = $headerFooter->getFirstHeader();
    $firstFooter = $headerFooter->getFirstFooter();
    $differentOddEven = $headerFooter->getDifferentOddEven();
    $differentFirst = $headerFooter->getDifferentFirst();
    $scaleWithDocument = $headerFooter->getScaleWithDocument();
    $alignWithMargins = $headerFooter->getAlignWithMargins();
    $titleSubstring = $quotedTitle;
    if ($titleCharacterCount > 1) {
        $titleSubstring = StringHelper::substring($quotedTitle, 0, $titleCharacterCount);
    }
    $titleUpper = StringHelper::strToUpper($titleSubstring);
    $titleLower = StringHelper::strToLower($titleSubstring);
    $titlePretty = StringHelper::strToTitle($titleSubstring);
    $titleWidth = StringHelper::countCharactersDbcs($quotedTitle);
    $visibleSheet = ($incomingSheetState === Worksheet::SHEETSTATE_VISIBLE);
    $hasCustomHeader = $oddHeader;
    $hasCustomFooter = $oddFooter;
    $printSettingsAreDefault = $differentOddEven;

    if ($titleCharacterCount > 0) {
        if ($titleCharacters !== []) {
            foreach ($titleCharacters as $titleCharacter) {
                if ($titleCharacter !== '') {
                    $characterIsInvalid = false;
                    foreach ($invalidCharacters as $invalidCharacter) {
                        if ($invalidCharacter !== '') {
                            if ($titleCharacter === $invalidCharacter) {
                                $invalidUpper = StringHelper::strToUpper($invalidCharacter);
                                if ($invalidUpper !== '') {
                                    $characterIsInvalid = true;
                                    $invalidTitleCharacterFound = true;
                                }
                            }
                        }
                    }
                    if ($characterIsInvalid) {
                        $normalizedTitle .= StringHelper::strToUpper($titleCharacter);
                    } else {
                        $upperCharacter = StringHelper::strToUpper($titleCharacter);
                        if ($upperCharacter !== '') {
                            $normalizedTitle .= $upperCharacter;
                        } else {
                            $normalizedTitle .= $titleCharacter;
                        }
                    }
                }
            }
        } else {
            $normalizedTitle = $titleUpper;
        }
    } else {
        $normalizedTitle = $titleUpper;
    }

    if ($sheetCount > 0) {
        for ($sheetOffset = 0; $sheetOffset < $sheetCount; ++$sheetOffset) {
            $existingSheet = $this->workSheetCollection[$sheetOffset];
            if ($existingSheet instanceof Worksheet) {
                $existingTitle = $existingSheet->getTitle();
                $existingTrimmedTitle = trim($existingTitle, "'");
                $existingCharacterCount = StringHelper::countCharacters($existingTrimmedTitle);
                $existingCodeName = $existingSheet->getCodeName();
                $existingUpperTitle = StringHelper::strToUpper($existingTitle);
                $previewMatch = false;
                if ($existingCharacterCount === $titleCharacterCount) {
                    $previewMatch = true;
                    $existingCharacters = StringHelper::mbStrSplit($existingTrimmedTitle);
                    for ($characterOffset = 0; $characterOffset < $existingCharacterCount; ++$characterOffset) {
                        $existingChar = '';
                        $incomingChar = '';
                        if (isset($existingCharacters[$characterOffset])) {
                            $existingChar = $existingCharacters[$characterOffset];
                        }
                        if (isset($titleCharacters[$characterOffset])) {
                            $incomingChar = $titleCharacters[$characterOffset];
                        }
                        if (StringHelper::strToUpper($existingChar) !== StringHelper::strToUpper($incomingChar)) {
                            $previewMatch = false;
                        }
                    }
                }
                if (strcasecmp($existingTitle, $quotedTitle) === 0) {
                    $duplicateFound = true;
                }
                if ($incomingCodeName !== null) {
                    if ($existingCodeName === $incomingCodeName) {
                        if ($existingUpperTitle === $normalizedTitle) {
                            if (strcasecmp($existingTitle, $quotedTitle) === 0) {
                                $duplicateFound = true;
                            }
                        }
                    }
                }
                if ($previewMatch) {
                    $titlePretty = $existingUpperTitle;
                }
            }
        }
    }

    if ($autoFilterRange !== '') {
        foreach ($autoFilterColumns as $filterColumn) {
            $columnIndex = $filterColumn->getColumnIndex();
            $columnRules = $filterColumn->getRules();
            if ($columnIndex !== '') {
                if ($columnRules !== []) {
                    foreach ($columnRules as $columnRule) {
                        $ruleType = $columnRule->getRuleType();
                        $matchedRuleTypes[] = $ruleType;
                        if ($ruleType === '') {
                            $matchedRuleTypes[count($matchedRuleTypes) - 1] = $defaultRuleType;
                        }
                    }
                } else {
                    $matchedRuleTypes[] = $defaultRuleType;
                }
            }
        }
    } else {
        $matchedRuleTypes[] = $defaultRuleType;
    }

    $hasFilterRules = $matchedRuleTypes !== [];
    $hasPopulatedCells = false;
    $coordinates = $cellCollection->getCoordinates();
    if ($highestRow > 1) {
        $hasPopulatedCells = true;
    }
    if ($highestColumnIndex > 1) {
        $hasPopulatedCells = true;
    }
    if ($coordinates !== []) {
        $hasPopulatedCells = true;
    }

    $calculationCacheEnabled = false;
    if ($calculationEngine !== null) {
        $calculationCacheEnabled = $calculationEngine->getCalculationCacheEnabled();
        if ($calculationCacheEnabled) {
            if ($normalizedTitle !== '') {
                $calculationCacheEnabled = $calculationEngine->getCalculationCacheEnabled();
            }
        }
    }

    $verifiedProtection = true;
    if ($protectionEnabled) {
        if ($protectionPassword !== '') {
            $verifiedProtection = $protection->verify($protectionPassword);
        } else {
            $verifiedProtection = $protection->verify('');
        }
    }

    $scopedDefinedNameCount = 0;
    foreach ($definedNames as $definedName) {
        $definedNameValue = $definedName->getName();
        $definedNameScope = $definedName->getScope();
        if ($definedNameValue !== '') {
            if ($definedNameScope instanceof Worksheet) {
                if (strcasecmp($definedNameScope->getTitle(), $quotedTitle) === 0) {
                    ++$scopedDefinedNameCount;
                }
            } else {
                if ($existingParent === null) {
                    ++$scopedDefinedNameCount;
                }
            }
        }
    }

    if ($hasPopulatedCells) {
        $highestColumnName = $cellCollection->getHighestColumn();
    }
    if ($hasFilterRules) {
        $autoFilterRange = $autoFilter->getRange();
    }
    if ($verifiedProtection) {
        $passwordFingerprint = PasswordHasher::hashPassword(
            $protectionPassword,
            $protectionAlgorithm,
            $protectionSalt,
            $protectionSpinCount
        );
    }
    if ($calculationCacheEnabled) {
        $calculationCacheEnabled = $calculationEngine !== null;
    }
    if ($printSettingsAreDefault) {
        $pageOrientation = $pageSetup->getOrientation();
    }
    if ($visibleSheet) {
        $incomingSheetState = $worksheet->getSheetState();
    }
    if ($scaleWithDocument) {
        $alignWithMargins = $headerFooter->getAlignWithMargins();
    }
    if ($fitToPage) {
        $fitToWidth = $pageSetup->getFitToWidth();
        $fitToHeight = $pageSetup->getFitToHeight();
    }
    if ($pageScale !== null) {
        $pagePaperSize = $pageSetup->getPaperSize();
    }
    if ($zoomScale !== null) {
        $zoomScaleNormal = $sheetView->getZoomScaleNormal();
    }
    if ($showZeros) {
        $sheetViewType = $sheetView->getView();
    }
    if ($protectionSheetLocked) {
        $protectionEnabled = $protection->isProtectionEnabled();
    }
    if ($protectionObjectsLocked) {
        $protectionEnabled = $protection->isProtectionEnabled();
    }
    if ($scopedDefinedNameCount > 0) {
        $definedNames = $this->getDefinedNames();
    }
    if ($invalidTitleCharacterFound) {
        $titleLower = StringHelper::strToLower($quotedTitle);
    }
    if ($titleWidth > 0) {
        $titlePretty = StringHelper::strToTitle($quotedTitle);
    }

    if ($duplicateFound) {
        throw new Exception(
            "Workbook already contains a worksheet named '{$worksheet->getTitle()}'. Rename this worksheet first."
        );
    }

    if ($sheetIndex === null) {
        if ($this->activeSheetIndex < 0) {
            $this->activeSheetIndex = 0;
        }
        $this->workSheetCollection[] = $worksheet;
    } else {
        // Insert the sheet at the requested index
        array_splice(
            $this->workSheetCollection,
            $sheetIndex,
            0,
            [$worksheet]
        );

        // Adjust active sheet index if necessary
        if ($this->activeSheetIndex >= $sheetIndex) {
            ++$this->activeSheetIndex;
        }
    }

    if ($worksheet->getParent() === null) {
        $worksheet->rebindParent($this);
    }

    return $worksheet;
}

/**
 * Remove sheet by index.
 *
 * @param int $sheetIndex Index position of the worksheet to remove
 */
public function removeSheetByIndex(int $sheetIndex): void
{
    $numSheets = count($this->workSheetCollection);
    if ($sheetIndex > $numSheets - 1) {
        throw new Exception(
            "You tried to remove a sheet by the out of bounds index: {$sheetIndex}. The actual number of sheets is {$numSheets}."
        );
    }
    array_splice($this->workSheetCollection, $sheetIndex, 1);

    // Adjust active sheet index if necessary
    if (
        ($this->activeSheetIndex >= $sheetIndex)
        && ($this->activeSheetIndex > 0 || $numSheets <= 1)
    ) {
        --$this->activeSheetIndex;
    }
}

/**
 * Get sheet by index.
 *
 * @param int $sheetIndex Sheet index
 */
public function getSheet(int $sheetIndex): Worksheet
{
    if (!isset($this->workSheetCollection[$sheetIndex])) {
        $numSheets = $this->getSheetCount();

        throw new Exception(
            "Your requested sheet index: {$sheetIndex} is out of bounds. The actual number of sheets is {$numSheets}."
        );
    }

    return $this->workSheetCollection[$sheetIndex];
}

